//! 🧪️ Borrowed own Part21 inverse bytes equal the central mutation contract under one original fuel unit.
use super::*;
use protocol::ColdMutation;
use std::mem::size_of;
use semio_framework_plugin::app_testing::OriginalWorkFixture;
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:2_097_152,maximum_release_bytes:2_097_152,maximum_depth:256}}
fn exact_ids(value:&mut DslValue){match value{DslValue::Object(fields)=>for(key,value)in fields{if key=="id"{if let DslValue::String(text)=value{*value=DslValue::uint(text.parse::<u64>().unwrap());}}else{exact_ids(value);}},DslValue::Array(values)=>for value in values{exact_ids(value);},_=>{}}}
fn native<T:FromValue>(value:&semio_framework_pack_json::Value)->T{let mut value=semio_framework_pack_json::to_dsl_value(value);exact_ids(&mut value);T::from_value(value).unwrap()}
fn encoded(source:store::ArtifactPreparedOperationSource<'_>,caller:&mut OriginalWorkFixture)->Vec<u8>{let mut cursor=store::ArtifactPreparedOperationCursor::default();let mut chunk=[0;64];let mut output=Vec::new();for _ in 0..200_000{let(written,complete)=caller.work_turn(grant(),1,|cx|{let progress=cursor.advance(source,&mut chunk,cx.retained_grant()).map_err(|error|error.reason)?;let result=(progress.written_bytes,progress.complete);cx.consume_retained(receipt(progress))?;Ok(result)}).unwrap();output.extend_from_slice(&chunk[..written]);if complete{for _ in 0..65536{if cursor.closed{return output;}caller.turn(grant(),|cx|cx.with_original_retirement(|cx|{let demand=cursor.retirement_demands()?;semio_framework_job::close_original_retained_step(cx,demand,|grant|{let progress=cursor.close(grant).map_err(|error|error.reason)?;let complete=progress.complete;let progress=receipt(progress);Ok(if complete{RetainedCloneStep::Complete(progress)}else{RetainedCloneStep::Progress(progress)})})?;Ok(())})).unwrap();}}}panic!("own Part21 expected wire did not finish")}
fn capture(snapshot:&Arc<Ifc2x3Snapshot>,caller:&mut OriginalWorkFixture)->Publication{let mut cursor=Publication::default();caller.work_turn(grant(),1,|cx|{let alias=size_of::<Arc<Ifc2x3Snapshot>>();let(source,mut progress)=Source::admit_borrowed(Arc::clone(snapshot),|snapshot|snapshot.as_ref(),RetainedCloneGrant{maximum_copy_bytes:cx.retained_grant().maximum_copy_bytes-alias,..cx.retained_grant()}).map_err(|(error,_)|error)?;progress.copied_bytes+=alias;cursor.view.source=Some(source);cx.consume_retained(progress)?;Ok(())}).unwrap();cursor}
fn close(cursor:&mut Publication,caller:&mut OriginalWorkFixture){for _ in 0..65536{if !cursor.codec_live(){break;}caller.turn(grant(),|cx|cx.with_original_retirement(|cx|{let demand=cursor.close_demands()?;semio_framework_job::close_original_retained_step(cx,demand,|grant|cursor.close_codec(grant))?;Ok(())})).unwrap();}assert!(!cursor.codec_live());let source=cursor.view.source.as_mut().unwrap();for _ in 0..65536{if source.terminal_is_empty(){return;}caller.turn(grant(),|cx|cx.with_original_retirement(|cx|{let demand=source.next_close_demand(grant().maximum_copy_bytes)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|source.close_step(grant))?;Ok(())})).unwrap();}panic!("own Part21 original source close did not drain")}
#[test]
fn own_borrowed_inverse_wire_matches_exact_central_operation_and_restores_every_neutral_case(){let fixture=semio_framework_pack_json::parse(include_str!("🧪️tests/wire.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();for row in fixture["cases"].as_array().unwrap(){let snapshot=Arc::new(native::<Ifc2x3Snapshot>(&fixture["snapshot"]));let mutation=native::<Ifc2x3Mutation>(&row["mutation"]);let expected=mutation.inverse(snapshot.as_ref()).unwrap();let mutations=vec![mutation];let mut caller=OriginalWorkFixture::new();let mut cursor=capture(&snapshot,&mut caller);let mut checked=false;let mut complete=false;for _ in 0..200_000{if matches!(cursor.phase,Phase::Forward)&&!checked{assert_eq!(matches!(cursor.view.inverse,Inverse::None),expected.is_empty());if let Some(inverse)=expected.first(){let expected=encoded(store::ArtifactPreparedOperationSource::CanonicalJson{header:b"op",body:store::ArtifactCanonicalTreeSource::view(inverse)},&mut caller);let view=InverseView{publication:&cursor.view};let actual=encoded(store::ArtifactPreparedOperationSource::CanonicalJson{header:b"op",body:&view},&mut caller);assert_eq!(actual,expected,"{}",row["name"].as_str().unwrap());}checked=true;}if caller.work_turn(grant(),1,|cx|cursor.advance(&mutations,semio_framework_plugin::retained_command::ArtifactRetainedWorkCapacity::for_invertible_items(1),cx)).unwrap(){complete=true;break;}}assert!(complete&&checked);let mut next=protocol::apply_diff_cold(mutations[0].diff(snapshot.as_ref()).diff(),snapshot.as_ref()).unwrap();for inverse in expected{next=protocol::apply_diff_cold(inverse.diff(&next).diff(),&next).unwrap();}assert_eq!(&next,snapshot.as_ref());close(&mut cursor,&mut caller);caller.finish();assert_eq!(Arc::strong_count(&snapshot),1);}}
